import{_ as a,o as r,c as i,a5 as t}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"Origin & Treatment Disclosure","description":"","frontmatter":{"title":"Origin & Treatment Disclosure","grading":"origin-disclosure"},"headers":[],"relativePath":"grading/origin-disclosure.md","filePath":"grading/origin-disclosure.md","lastUpdated":1790876393000}'),n={name:"grading/origin-disclosure.md"};function s(o,e,l,d,c,u){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="origin-treatment-disclosure" tabindex="-1">Origin &amp; Treatment Disclosure <a class="header-anchor" href="#origin-treatment-disclosure" aria-label="Permalink to &quot;Origin &amp; Treatment Disclosure&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Treatment status and origin opinions belong to disclosure and laboratory-report contexts. Requirements depend on jurisdiction, rules, reports, and transaction context; they are not one grading scale.</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-origin-disclosure-en"><p class="gem-identification-boundary__eyebrow">GRADING BOUNDARY</p><h2 id="identification-boundary-origin-disclosure-en">Boundary &amp; Safety</h2><p>This page separates treatment disclosure from origin opinions; it does not provide legal advice, price forecasts, or a final disclosure conclusion for a specimen. Any “must disclose” statement must be tied to a jurisdiction, rule, report, and transaction context; high-value transactions should use qualified laboratory and professional advice. </p></aside><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>“No Indications of Treatment” means no treatment indications were observed; it is not absolute proof of never-treated, and price is not determined by this alone.</li><li>Routine treatment (e.g. heat on sapphire / ruby): disclosure depends on the applicable rules, report, and transaction context.</li><li>Enhancement (oil/resin in emerald, dye, fracture filling): explain stability, care, report wording, and disclosure scope together.</li><li>Origin opinion: based on inclusion suites and trace chemistry, may be inconclusive, and is not a grade.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Grade</th><th>Note</th></tr></thead><tbody><tr><td>ruby</td><td>heated (H)</td><td>Treatment-disclosure example; does not set a price cap alone</td></tr><tr><td>emerald</td><td>minor oil (Cedarwood)</td><td>Read with stability, care, report wording, and applicable rules</td></tr><tr><td>sapphire</td><td>unheated, Kashmir</td><td>No treatment indication and origin opinion are separate dimensions</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page explains grading descriptions and report terms; the sources document the knowledge basis and do not make this page sufficient for grading, valuing, identifying, or determining the origin of a specific specimen.</p><ul><li><a href="https://www.gia.edu/diamond-quality-factor" target="_blank" rel="noreferrer">GIA: Diamond Quality Factors</a><span>Diamond quality factors including color, clarity, cut, and carat weight; not a price formula</span><small>Open source ↗</small></li><li><a href="https://4cs.gia.edu/en-us/diamond-clarity/" target="_blank" rel="noreferrer">GIA 4Cs: Diamond Clarity</a><span>Introductory explanation of FL–I3 clarity grades and the 10× observation condition</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/value-factors-design-cut-quality-colored-gemstone-value-factors" target="_blank" rel="noreferrer">GIA: Colored Gemstone Value Factors</a><span>Colour, cut, clarity, durability, and market factors vary by gemstone species</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/UK-EN/emerald-quality-factor" target="_blank" rel="noreferrer">GIA: Emerald Quality Factors</a><span>Species-specific context for emerald colour, transparency, inclusions, and treatment</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA: Analytical Methods Used in Geographic Origin Determination</a><span>Origin opinions use multiple evidence types and may remain inconclusive</span><small>Open source ↗</small></li><li><a href="https://www.ftc.gov/news-events/topics/tools-consumers/jewelry-guides" target="_blank" rel="noreferrer">FTC: Jewelry, Precious Metals, and Pewter Industries Guides</a><span>US consumer and marketing disclosure guidance; not automatically the law of every jurisdiction</span><small>Open source ↗</small></li></ul></aside><aside class="gem-reference-block gem-evidence-ledger" aria-labelledby="gem-evidence-title-origin-disclosure-en"><p class="gem-reference-block__eyebrow">EVIDENCE MAP</p><h2 id="gem-evidence-title-origin-disclosure-en">Evidence map for this page</h2><p class="gem-reference-block__intro">Claims are mapped to references and labelled with their evidence status in this knowledge base.</p><ul><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">Source-supported</strong><span>Origin is a laboratory opinion based on multiple evidence types, may be inconclusive, and is not a gemstone grade.</span><small>GIA: Analytical Methods Used in Geographic Origin Determination</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">Source-supported</strong><span>Treatment disclosure requirements depend on the applicable jurisdiction, rules, report, and transaction context; they are not one universal legal conclusion.</span><small>FTC: Jewelry, Precious Metals, and Pewter Industries Guides</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">Teaching summary</strong><span>Treatment status can affect report interpretation, stability, care, and market assessment, but a treatment label alone does not set a price cap.</span><small>GIA: Emerald Quality Factors; FTC: Jewelry, Precious Metals, and Pewter Industries Guides</small></li></ul></aside><p><em>See the <a href="./intro.html">grading overview</a>.</em></p>',11)])])}const g=a(n,[["render",s]]);export{m as __pageData,g as default};
